use crate::common;
use rust_xlsxwriter::{Formula, IgnoreError, Workbook, XlsxError};

// Create rust_xlsxwriter file to compare against Excel file.
fn create_new_xlsx_file(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();
    let worksheet = workbook.add_worksheet();

    let formula = Formula::new(r#"=DATEVALUE("1/1/30")"#).set_result("10959");
    worksheet.write_formula(0, 0, formula)?;

    worksheet.ignore_error(0, 0, IgnoreError::TwoDigitTextYear)?;

    workbook.save(filename)?;

    Ok(())
}

#[test]
fn test_ignore_error07() {
    let test_runner = common::TestRunner::new()
        .set_name("ignore_error07")
        .set_function(create_new_xlsx_file)
        .ignore_calc_chain()
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}
